package dev.shadw.khemet.mobs;

import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.MobRenderer;
import net.minecraft.resources.ResourceLocation;

/** Renders the Royal Mummy with its own model and texture. Generated by shadw-mod mob. */
public class RoyalMummyRenderer extends MobRenderer<RoyalMummy, RoyalMummyModel.State, RoyalMummyModel> {
	private static final ResourceLocation TEXTURE = ResourceLocation.fromNamespaceAndPath("khemet", "textures/entity/royal_mummy.png");

	public RoyalMummyRenderer(EntityRendererProvider.Context context) {
		super(context, new RoyalMummyModel(context.bakeLayer(RoyalMummyModel.LAYER)), 0.5F);
	}

	@Override
	public RoyalMummyModel.State createRenderState() {
		return new RoyalMummyModel.State();
	}

	@Override
	public void extractRenderState(RoyalMummy entity, RoyalMummyModel.State state, float partialTick) {
		super.extractRenderState(entity, state, partialTick);
		state.attackTime = entity.getAttackAnim(partialTick);
	}

	@Override
	public ResourceLocation getTextureLocation(RoyalMummyModel.State state) {
		return TEXTURE;
	}
}
